348	  private _buildPlanes(textures: (THREE.Texture | null)[]): void {
349	    const count = textures.length;
350	    if (count === 0) return;
351	    const scene = this._scene!;
352	
353	    for (let i = 0; i < VISIBLE_COUNT; i++) {
354	      // Spatial spread matching the original golden-angle distribution
355	      const hAngle = (i * 2.618) % (Math.PI * 2);
356	      const vAngle = (i * 1.618 + Math.PI / 3) % (Math.PI * 2);
357	      const hRadius = (i % 3) * 1.2;
358	      const vRadius = ((i + 1) % 4) * 0.8;
359	      const x = (Math.sin(hAngle) * hRadius * MAX_HORIZONTAL_OFFSET) / 3;
360	      const y = (Math.cos(vAngle) * vRadius * MAX_VERTICAL_OFFSET) / 4;
361	      const z = (DEPTH_RANGE / VISIBLE_COUNT) * i;
362	      const imageIndex = i % count;
363	
364	      const geo = new THREE.PlaneGeometry(1, 1, 32, 32);
365	      this._geometries.push(geo);
366	
367	      const mat = new THREE.ShaderMaterial({
368	        transparent: true,
369	        uniforms: {
370	          map: { value: textures[imageIndex] ?? null },
371	          opacity: { value: 0.0 },
372	          blurAmount: { value: 0.0 },
373	          scrollForce: { value: 0.0 },
374	          time: { value: 0.0 },
375	          isHovered: { value: 0.0 },
376	        },
377	        vertexShader: VERTEX_SHADER,
378	        fragmentShader: FRAGMENT_SHADER,
379	      });
380	      this._materials.push(mat);
381	
382	      const mesh = new THREE.Mesh(geo, mat);
383	      mesh.position.set(x, y, z - HALF_RANGE);
384	      this._applyTextureScale(mesh, textures[imageIndex] ?? null);
385	
386	      scene.add(mesh);
387	      this._planes.push({ mesh, data: { index: i, z, imageIndex, x, y } });
388	      this._meshList.push(mesh);
389	    }
390	  }
