392	  private _applyTextureScale(
393	    mesh: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial>,
394	    tex: THREE.Texture | null,
395	  ): void {
396	    const img = tex?.image as { width?: number; height?: number } | undefined;
397	    if (img?.width && img.height) {
398	      const aspect: number = img.width / img.height;
399	      mesh.scale.set(aspect > 1 ? 4 * aspect : 4, aspect > 1 ? 4 : 4 / aspect, 1);
400	    } else {
401	      mesh.scale.set(4, 4, 1);
402	    }
403	  }
