**Rotation Strategy** (`ProofRotationStrategy.ts`, lines 20-38):
```typescript
export class ScrollAcceleratingRotation implements ProofRotationStrategy {
  feed(progress: number, delta: number): void {
    this._progress = progress;
    this._velocity += delta;
  }

  next(): number {
    this._velocity *= this._cfg.decayFactor;  // 0.88
    return (
      this._cfg.baseSpeed * (1 + this._progress * this._cfg.progressScale + this._velocity * this._cfg.velocityScale)
    );
    // = 0.0005 * (1 + progress*1.8 + velocity*100)
  }
}
```

